import {
  data,
  operation,
  resource,
  tag,
  readMany,
  type Data,
  type Many,
  type Operation,
  type Resource,
  type Scope,
  type Tag,
} from "@tinker/core";

export type { Errors } from "./errors.ts";
export { isError } from "./errors.ts";
